#!/usr/bin/env python3
"""Fresh-process median timer: 3 warmups, 11 samples, rotating order."""
import json
import statistics
import subprocess
import sys
import time
from pathlib import Path

import os
WARMUPS = int(os.environ.get('WARMUPS', '3'))
SAMPLES = int(os.environ.get('SAMPLES', '11'))


def run_once(path):
    start = time.perf_counter_ns()
    out = subprocess.run([path], capture_output=True, text=True, timeout=300)
    elapsed = time.perf_counter_ns() - start
    if out.returncode != 0:
        raise SystemExit(f"{path} failed: {out.stderr}")
    return elapsed / 1e6, out.stdout.strip()


def main():
    paths = [Path(p).resolve() for p in sys.argv[1:]]
    results = {p.name: [] for p in paths}
    outputs = {}
    for _ in range(WARMUPS):
        for p in paths:
            run_once(p)
    for index in range(SAMPLES):
        order = paths if index % 2 == 0 else list(reversed(paths))
        for p in order:
            ms, text = run_once(p)
            results[p.name].append(ms)
            outputs[p.name] = text
    summary = {}
    for p in paths:
        values = sorted(results[p.name])
        summary[p.name] = {
            "median_ms": round(statistics.median(values), 3),
            "min_ms": round(values[0], 3),
            "max_ms": round(values[-1], 3),
            "stdout": outputs[p.name],
            "samples": [round(v, 3) for v in values],
        }
    print(json.dumps(summary, indent=1))


if __name__ == "__main__":
    main()

