import * as text from "std/text";
import { println, Error as IoError } from "std/io";

fn main(): Result<void, IoError> {
  const lines = [
    "книга море книга дом",
    "море свет дом книга",
    "rust go marimay go",
    "ёжик туман ёжик книга",
  ];
  let checksum = 0;
  for repeat in 0..10 {
    const counts: Map<string, int> = mapOf<string, int>();
    for index in 0..10_000 {
      const words = match text.split(lines[index % 4], " ", 16) {
        Ok(value) => value,
        Err(_) => panic("split failed"),
      };
      for word in words {
        const count = match counts.get(word) {
          Some(value) => value,
          None => 0,
        };
        match counts.put(word, count + 1) {
          Ok(_) => {},
          Err(_) => panic("map failed"),
        };
      }
    }
    checksum = checksum + counts.length();
  }
  println($"full {checksum}")?;
  return Ok();
}

