  let pattern: []int = [];
  for index in 0..15 {
    const _ = pattern.push(0x4D + index * 7);
  }
  const counts: Map<int, int> = mapOf<int, int>();
  let checksum = 0;
  for repeat in 0..30_000 {
    for value in pattern {
      const next = match counts.get(value) {
        Some(count) => count + 1,
        None => 1,
      };
      const _ = counts.put(value, next);
    }
  }
  checksum = checksum + counts.length();
  println($"int-map {checksum}")?;
  return Ok();
}

